// The one entry. Two modes, one machine, the Waterfall Contacts Batch pattern (Operator ruling
// 2026-09-03, who refused three sub-workflows for this):
//   prepare  turns a launch row into a resolved, DNC-filtered, capped, merge-shaped payload,
//            and hands the caller everything it needs to send.
//   finish   takes that payload back with the send results on it, stamps the source rows,
//            writes the Lead Lists receipt and writes the run's Hub row.
// The caller owns the send and nothing else. Both deploy doors call this; they differ only in how
// they push, which is the one thing that cannot be shared.
// A sub-workflow carries no Error Logger (logging standard, 2026-09-02): every refusal here is
// either a named abort riding the state, or a throw that fails the caller, whose own crash is what
// gets the Failed row. The contract is checked before anything is read or written.
const raw = $input.first().json || {};
const inp = Object.assign({}, raw);
const mode = String(inp.mode || '').trim().toLowerCase();
const who = 'Deploy View Prepare and Finish';
if (mode !== 'prepare' && mode !== 'finish') throw new Error(who + ' was called with mode "' + String(inp.mode || '') + '"; only "prepare" and "finish" exist.');
const sender = String(inp.sender || '').trim();
if (sender !== 'PlusVibe' && sender !== 'Alta' && sender !== 'Email Bison') throw new Error(who + ' (' + mode + ') was called with sender "' + sender + '"; only "PlusVibe", "Alta" and "Email Bison" exist.');
if (!String(inp.execId || '').trim()) throw new Error(who + ' (' + mode + ') was called without execId; the Hub row is keyed by the calling execution, never by this one.');
if (!String(inp.automation || '').trim()) throw new Error(who + ' (' + mode + ') was called without automation; the Hub row names the door that ran, never this helper.');
if (mode === 'prepare' && !/^rec[A-Za-z0-9]{14}$/.test(String(inp.recordId || ''))) throw new Error(who + ' (prepare) was called without a launch row id. Nothing was read.');
if (mode === 'finish' && (!inp.state || typeof inp.state !== 'object')) throw new Error(who + ' (finish) was called without the state prepare returned. Nothing was written.');
inp.mode = mode;
inp.sender = sender;
inp.execId = String(inp.execId);
inp.wfId = String(inp.wfId || '');
inp.recordId = String(inp.recordId || '');
return [{ json: inp }];

// Init Deploy: the launch row into the run's state. One launch = one view into one campaign:
// Client link, Table (People or Companies, by name, required), View (id or exact name, required),
// Target (the sequencer's campaign id), Dedupe Mode (PlusVibe only), Max Rows.
// No defaults (Operator ruling 2026-09-02): a launch row that leaves Table or View blank is
// refused here, before anything is read or sent.
// Max Rows is optional and blank means unlimited: the most rows this run may enrol, applied in
// Build Rows to the rows that survive every other check. The Airtable feed sets it per sequencer;
// a hand-launched deploy leaves it blank unless the Operator wants a slice.
// The launch row is read from Read Launch Row by name, never from $input: Stamp Running sits
// between them and hands on its own item (or its error item, when there is no row to stamp).
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const call = $('Route Mode').first().json;
let r = {}; try { r = ($('Read Launch Row').first() || {}).json || {}; } catch (e) {}
const f = r.fields || r;
const cid = Array.isArray(f['Client']) ? f['Client'][0] : null;
const isPV = call.sender === 'PlusVibe';
const D = {
  sender: call.sender, automation: String(call.automation || ''),
  execId: String(call.execId), wfId: String(call.wfId || ''),
  launchId: String(r.id || ''),
  clientId: (cid && typeof cid === 'object') ? String(cid.id || '') : String(cid || ''),
  table: String((f['Table'] && f['Table'].name) || f['Table'] || '').trim(), tableId: '', tableName: '',
  view: String(f['View'] || '').trim(), viewId: '', viewType: '',
  target: String(f['Target'] || '').trim(),
  dedupe: String((f['Dedupe Mode'] && f['Dedupe Mode'].name) || f['Dedupe Mode'] || 'Strict').trim() || 'Strict',
  maxRows: Math.max(0, Math.floor(Number(f['Max Rows']) || 0)),
  // The launch row's own Trigger is kept and written back unchanged: the Airtable feed stamps
  // "schedule" on the rows it creates, and a hand launch is "form". The door never overrides it.
  trigger: String((f['Trigger'] && f['Trigger'].name) || f['Trigger'] || '').trim() || 'form',
  clientName: '', ws: '', crBase: '', share: '', regTableId: '',
  campName: '', hubCampaignRid: '', pullInUrl: '',
  dncTableId: '', mirrorTableId: '', stampMirrorRid: '', shareViewLink: '', hasDeployError: false,
  linkedinCol: '', plan: { varCols: [], rideCols: [] }, requiredCore: [], needFirstName: true,
  rows: {}, varMisses: {}, skipCounts: {}, rowsTotal: 0,
  emailToRow: {}, urlToRow: {}, inCamp: {}, freshProspects: {},
  uploadedNew: 0, deployed: 0, landed: 0, pushed: 0, missing: 0, campsStamped: 0,
  pausedTitle: 0, pausedUrl: 0, pausedNoData: 0, pausedNames: [], campaignProspects: 0,
  rbFailed: false, ready: false,
  errors: [], warnings: [], abort: null,
  startedAt: Date.now(), runAt: $now.toISO()
};
if (!D.launchId) { D.abort = 'launch row not found'; D.errors.push('launch row not found (recordId missing or invalid)'); }
// Stamp Running never gates, so a real Airtable failure there would be silent. It is not: a launch
// row that exists but could not be claimed leaves finish upserting a NEW row on this execution id
// instead of closing the launch row, and that has to be readable on the row it does write.
if (D.launchId) {
  try { const s = ($('Stamp Running').first() || {}).json || {}; if (s.error) D.errors.push('could not stamp the launch row Running: ' + JSON.stringify(s.error).slice(0, 200) + '; this run logs to a new row instead of closing the launch row'); } catch (e) {}
}
if (!D.abort && !D.clientId) { D.abort = 'no client link'; D.errors.push('launch row has no Client link'); }
if (!D.abort && !D.table) { D.abort = 'no Table'; D.errors.push('launch row has no Table (People or Companies); nothing was sent'); }
if (!D.abort && !D.view) { D.abort = 'no View'; D.errors.push('launch row has no View; nothing was sent'); }
if (!D.abort) {
  // Email Bison campaign ids are plain integers (e.g. 601); the door proves the id exists by GET.
  const isBison = call.sender === 'Email Bison';
  const ok = isPV ? /^[0-9a-f]{24}$/i.test(D.target) : (isBison ? /^[0-9]{1,10}$/.test(D.target) : /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(D.target));
  if (!ok) { D.abort = 'invalid Target'; D.errors.push('Target "' + D.target + '" is not ' + (isPV ? 'a plausible PlusVibe campaign id (24 hex)' : (isBison ? 'an Email Bison campaign id (integer)' : 'an Alta campaign UUID'))); }
}
sd[dk] = D;
return [{ json: { clientId: D.clientId || 'recMISSING' } }];

// Check Client: the registry row into the run's state. The ClayRoots base is the address of the
// table the view lives on; nothing about a client is hardcoded anywhere in this machine. The
// PlusVibe lane also needs the workspace the campaign lives in; the Alta lane does not, its
// address is the campaign's own Pull-in URL.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
if (!D.abort) {
  const r = ($input.first() || {}).json || {};
  const f = r.fields || r;
  D.clientName = String(f['Client name'] || f['Client'] || '').trim();
  D.ws = String(f['PlusVibe Workspace ID'] || '').trim();
  D.crBase = String(f['Clayroots Base ID'] || '').trim();
  // The registry carries the client's table ids (ClayrootsPeopleTableID / ClayrootsCompaniesTableID);
  // Plan Base reads the launch's table by that id first, by name on the base schema when absent.
  const tl = String(D.table || '').trim().toLowerCase();
  D.regTableId = String((tl === 'companies' ? f['ClayrootsCompaniesTableID'] : (tl === 'people' ? f['ClayrootsPeopleTableID'] : '')) || '').trim();
  // Shared-base link, used to build a deep link to the exact deployed view on the receipt.
  D.share = String(f['Clayroots shareable link'] || f['Clayroots Shareable Link'] || '').trim().replace(/\/+$/, '');
  if (D.sender === 'PlusVibe') {
    if (!D.ws || !/^app[A-Za-z0-9]{14}$/.test(D.crBase)) { D.abort = 'client not deployable'; D.errors.push('client missing PlusVibe Workspace ID or Clayroots Base ID'); }
  } else if (!/^app[A-Za-z0-9]{14}$/.test(D.crBase)) {
    D.abort = 'no ClayRoots base'; D.errors.push('client "' + (D.clientName || D.clientId) + '" has no valid Clayroots Base ID');
  }
}
return [{ json: { abort: !!D.abort, target: D.target || '' } }];

// Check Campaign: the Hub Campaigns row for the target, the one place both doors agree the
// campaign is described. It carries the campaign's name (the receipt is named by it), the Hub
// row the receipt links to, and, on the Alta lane, the Pull-in URL: the audience webhook Alta
// hands out per campaign, which no API exposes, so it is operator-pasted state on the row.
// Alta refuses without it. PlusVibe only warns on a missing Hub row, exactly as before: its
// campaign is proven to exist by the workspace listing the door itself does before sending.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
if (!D.abort) {
  const rows = $input.all().map(i => i.json).filter(r => r && (r.id || r.fields));
  const hit = rows[0];
  if (!hit) {
    if (D.sender === 'Alta') { D.abort = 'campaign not in Hub'; D.errors.push('no Campaigns row with Campaign ID ' + D.target + '; sync or create it first'); }
    else { D.campName = D.target; D.warnings.push('no Hub Campaigns row for ' + D.target + '; receipt created without campaign link'); }
  } else {
    const f = hit.fields || hit;
    D.hubCampaignRid = hit.id || '';
    D.campName = String(f['Campaign'] || D.target);
    const seq = String((f['Sequencer'] && f['Sequencer'].name) || f['Sequencer'] || '');
    // Email Bison: like PlusVibe, the campaign's existence is proven by the door's own GET, so a
    // missing Hub row only warns; a Hub row sequenced by someone else is a wrong Target, refused.
    if (D.sender === 'Email Bison' && seq && seq !== 'Email Bison') { D.abort = 'not an Email Bison campaign'; D.errors.push('campaign "' + D.campName + '" is sequenced by ' + seq + ', not Email Bison'); }
    if (D.sender === 'Alta') {
      if (seq && seq !== 'Alta') { D.abort = 'not an Alta campaign'; D.errors.push('campaign "' + D.campName + '" is sequenced by ' + seq + ', not Alta'); }
      D.pullInUrl = String(f['Pull-in URL'] || '').trim();
      if (!D.abort && !/^https:\/\/api\.altahq\.com\/audience\/webhook\/[0-9a-f-]+\/pull-in-prospect$/i.test(D.pullInUrl)) {
        D.abort = 'no Pull-in URL'; D.errors.push('campaign "' + D.campName + '" has no valid Pull-in URL on its Campaigns row; paste the audience webhook from Alta');
      }
    }
  }
}
return [{ json: { abort: !!D.abort, crBase: D.crBase || '', target: D.target || '', metaUrl: 'https://api.airtable.com/v0/meta/bases/' + (D.crBase || 'missing') + '/tables' } }];

// Plan Base: the client base's schema into the run's plan. Resolves, in one read:
//   the table the launch named (the registry's id first, the name on the schema second),
//   the view (by id or exact name; ids are rename-proof and Campaigns.Live View ID holds ids),
//   the DNC table (by name; absent = no deploy-time DNC filtering, and the run log says so),
//   the campaigns mirror table (Campaign ID + Sequencer, no Final Email, the signature the
//     sequencer syncs use),
//   the client-facing share link from the table description (the receipt's List URL; the API
//     cannot mint share links, so it is pasted there at setup),
//   and the table's field names, which Plan Contract turns into the merge contract.
// Any view the launch row names deploys (Operator ruling 2026-09-02): the old gate that accepted
// only "... : Campaigns" views is gone.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
// Every return carries the addresses the nodes downstream read off this node's output.
const shape = (extra) => Object.assign({ ok: false, viewUrl: '', crBase: D.crBase || 'appMISSING', tableId: D.tableId || '', dncTableId: D.dncTableId || '', mirrorTableId: D.mirrorTableId || 'tblMISSING', target: D.target || '' }, extra || {});
if (D.abort) { return [{ json: shape() }]; }
let tables = [];
try { const j = ($input.first() || {}).json || {}; tables = Array.isArray(j.tables) ? j.tables : []; } catch (e) {}
if (!tables.length) {
  let j = {}; try { j = ($input.first() || {}).json || {}; } catch (e) {}
  D.abort = 'could not read base schema';
  D.errors.push('could not read base schema for ' + D.crBase + (j.error ? ': ' + JSON.stringify(j.error).slice(0, 150) : ''));
  return [{ json: shape() }];
}
const want = String(D.table || '').trim();
let t = D.regTableId ? tables.find(x => x.id === D.regTableId) : null;
if (!t && D.regTableId) D.warnings.push('registry ' + want + ' table id ' + D.regTableId + ' is not in base ' + D.crBase + '; resolved by name instead');
if (!t) t = want ? tables.find(x => String(x.name || '').trim().toLowerCase() === want.toLowerCase()) : null;
if (!t) {
  D.abort = 'table not found';
  D.errors.push('Base ' + D.crBase + ' has no ' + (want || '(blank)') + ' table. Scaffold the base first. Nothing was spent or written.');
  return [{ json: shape() }];
}
D.tableId = t.id; D.tableName = t.name || t.id;
// The client-facing share link lives in the table description ("Campaigns view:
// https://airtable.com/shr..."), pasted at setup.
const m = String(t.description || '').match(/https:\/\/airtable\.com\/(?:app[A-Za-z0-9]{14}\/)?shr[A-Za-z0-9]+/);
D.shareViewLink = m ? m[0] : '';
if (!D.shareViewLink) D.warnings.push('table "' + D.tableName + '" description carries no share link; receipt written without a client link');
const v = (t.views || []).find(x => x.id === D.view || String(x.name || '').trim() === D.view);
if (!v) {
  D.abort = 'view not found';
  D.errors.push('view "' + D.view + '" is not on table "' + D.tableName + '" in base ' + D.crBase + '; nothing was sent');
  return [{ json: shape() }];
}
D.viewId = v.id; D.viewType = v.type || '';
const dncT = tables.find(x => String(x.name).toLowerCase() === 'dnc');
D.dncTableId = dncT ? dncT.id : '';
if (!D.dncTableId) D.warnings.push('no DNC table in base; DNC domains were not filtered at deploy time');
const mirT = tables.find(x => { const ns = new Set((x.fields || []).map(f => f.name)); return !ns.has('Final Email') && ns.has('Campaign ID') && ns.has('Sequencer'); });
D.mirrorTableId = mirT ? mirT.id : '';
if (!D.mirrorTableId) D.warnings.push('no campaigns mirror table in base (Campaign ID + Sequencer, no Final Email); Campaigns links not stamped');
const fields = t.fields || [];
D.fieldsById = {}; const names = new Set();
for (const f of fields) { D.fieldsById[f.id] = f.name; names.add(f.name); }
D.fieldNames = Array.from(names);
D.hasDeployError = names.has('Deploy Error');
// The lead's LinkedIn URL column: `LinkedIn URL` on a register-shaped table; `Social` only on a
// legacy table that has no `LinkedIn URL`. Never both, never guessed.
D.linkedinCol = names.has('LinkedIn URL') ? 'LinkedIn URL' : (names.has('Social') ? 'Social' : '');
// The view's visible field ids are the merge contract; only a grid view has them.
const viewUrl = ((v.type || 'grid') === 'grid') ? ('https://api.airtable.com/v0/meta/bases/' + D.crBase + '/views/' + v.id + '?include=visibleFieldIds') : '';
return [{ json: shape({ ok: true, viewUrl }) }];

// Plan Contract: THE RULE. The view's visible columns are the merge contract: every visible
// column is a variable and a row with an empty one is skipped. Three exceptions, in order:
// MACHINE columns are never read and never sent (the register's machine fields: the email lane,
// the Campaigns link and the sync's fields, the relevance and identity formulas, the contact
// provenance, the contact-pull stamps; taken from the field register the push inlines as REGISTER
// at the @@register line, every name checked against it so the list cannot drift); IDENTITY
// columns become the lead itself, never a variable; IGNORE columns ride along when filled and
// never block. A column on the table that is not on the register is the Operator's and deploys
// as a variable like any other visible column.
// The two lanes differ only in what identity is and in which columns never block: PlusVibe's
// identity is the email plus a first name and a company, and it also enforces the standard lead
// fields (State, City, Country) when the view shows them; Alta's identity is the LinkedIn URL
// plus a company, and the name rides along because Alta resolves the person from the URL.
// PlusVibe also refuses here, before a single lead is sent, when the source table lacks a column
// this door writes back: a client base is set up once, by the scaffold, and no working machine
// creates a column (Operator ruling 2026-09-02). The throw fails this sub-workflow, and with it
// the door that called it, which is where the Failed row belongs.
const REGISTER = {"tables":[{"name":"Companies","primary":"Domain","fields":[{"name":"Domain","kind":"plain","type":"singleLineText","company":true},{"name":"Company","kind":"plain","type":"singleLineText","company":true},{"name":"Description","kind":"plain","type":"multilineText","company":true},{"name":"Industry Groups","kind":"plain","type":"singleLineText","company":true},{"name":"Business Model","kind":"plain","type":"singleLineText","company":true},{"name":"Employees","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"1-10","color":"blueLight2"},{"name":"11-50","color":"cyanLight2"},{"name":"51-200","color":"tealLight2"},{"name":"201-500","color":"greenLight2"},{"name":"501-1000","color":"yellowLight2"},{"name":"1001-5000","color":"orangeLight2"},{"name":"5001-10000","color":"redLight2"},{"name":"10001+","color":"purpleLight2"}]},"company":true},{"name":"Revenue Range","kind":"plain","type":"singleLineText","company":true},{"name":"Keywords","kind":"plain","type":"singleLineText","company":true},{"name":"Country","kind":"plain","type":"singleLineText","company":true},{"name":"State","kind":"plain","type":"singleLineText","company":true},{"name":"City","kind":"plain","type":"singleLineText","company":true},{"name":"Street","kind":"plain","type":"singleLineText","company":true},{"name":"Zip","kind":"plain","type":"singleLineText","company":true},{"name":"Phones","kind":"plain","type":"singleLineText","company":true},{"name":"Public Emails","kind":"plain","type":"singleLineText","company":true},{"name":"Social URLs","kind":"plain","type":"singleLineText","company":true},{"name":"public_emails_clean","kind":"plain","type":"singleLineText","company":true},{"name":"MX Provider","kind":"plain","type":"singleLineText","company":true},{"name":"Redirect Domain","kind":"plain","type":"singleLineText","company":true},{"name":"Domain Source","kind":"plain","type":"singleLineText","company":true},{"name":"Tag","kind":"plain","type":"singleLineText","company":true},{"name":"Build Date","kind":"formula","formula":"CREATED_TIME()","refs":[]},{"name":"Contacts Pulled At","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"}},{"name":"Contacts Count","kind":"count","via":"People"},{"name":"Contact Sources","kind":"rollup","via":"People","field":"Contact Source","formula":"ARRAYUNIQUE(values)"},{"name":"Signals","kind":"mirrorLink","mirror":"Signals","company":true},{"name":"Signal At","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"},"company":true},{"name":"ICP Reason","kind":"plain","type":"multilineText","company":true},{"name":"Email","kind":"plain","type":"singleLineText"},{"name":"MV P0","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"ok","color":"greenBright"},{"name":"catch_all","color":"yellowBright"},{"name":"invalid","color":"redBright"},{"name":"disposable","color":"orangeLight2"},{"name":"unknown","color":"grayBright"},{"name":"error","color":"orangeBright"},{"name":"skipped","color":"grayLight2"}]}},{"name":"BB","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"verifying","color":"blueBright"},{"name":"deliverable","color":"greenBright"},{"name":"undeliverable","color":"redBright"},{"name":"risky","color":"yellowBright"},{"name":"unknown","color":"grayBright"},{"name":"error","color":"orangeBright"},{"name":"skipped","color":"grayLight2"}]}},{"name":"Final Email","kind":"plain","type":"singleLineText"},{"name":"Status","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"done","color":"greenBright"},{"name":"verifying","color":"blueBright"},{"name":"no_email_found","color":"redBright"},{"name":"error","color":"orangeBright"}]}},{"name":"Campaigns","kind":"mirrorLink","mirror":"Campaigns"},{"name":"Sequencers","kind":"mirrorLookup","mirror":"Campaigns","field":"Sequencer","description":"The senders that already hold this r