    const flagMap = { 'Standard': { skip_lead_in_active_pause_camp: true }, 'Strict': { skip_if_in_workspace: true }, 'Active-only': { skip_lead_for_active_only_camp: true }, 'None': {} };
    D.flags = Object.assign({ is_overwrite: true }, flagMap[D.dedupe] || flagMap['Strict']);
  }
  D.ready = chunks.length > 0;
} else {
  D.pushes = pushes;
  D.ready = pushes.length > 0;
}
return [{ json: { ready: D.ready, abort: false } }];

// Prepare Out: everything the caller needs, on one item. The state travels as DATA from here on,
// never as static data across the call boundary: the door carries it through its send lane and
// hands it straight back to finish. Two runs died at an Alta readback because workflow static data
// does not survive a Wait resume (2026-08-31 and 2026-09-01); an item does.
// The slot this run used in THIS machine's static data is deleted, not nulled: every prepare would
// otherwise leave a key behind forever.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
delete sd[dk];
// isPV is the EMAIL lane (PlusVibe and Email Bison both queue chunks); the first chunk's request
// body is shaped per sender below.
const isPV = D.sender === 'PlusVibe' || D.sender === 'Email Bison';
const isBison = D.sender === 'Email Bison';
const out = {
  ok: !D.abort,
  ready: !D.abort && !!D.ready,
  abort: D.abort || '',
  rowsTotal: D.rowsTotal || 0,
  queued: isPV ? ((D.send && D.send.queue) ? D.send.queue.reduce((n, c) => n + (c ? c.length : 0), 0) : 0) : (D.pushes || []).length,
  ws: D.ws || '', target: D.target || '', campName: D.campName || '', launchId: D.launchId || '',
  state: D
};
if (isPV) {
  const q = (D.send && D.send.queue) || [];
  out.body = q.length
    ? (isBison ? Object.assign({ leads: q[0] }, D.flags || {}) : Object.assign({ workspace_id: D.ws, campaign_id: D.target, leads: q[0] }, D.flags || {}))
    : null;
} else {
  out.pushes = D.pushes || [];
  D.pushes = null;
}
return [{ json: out }];

// Build Stamps: the source rows get the truth of this run written back onto them. Confirmed
// members get this campaign's mirror row unioned into their Campaigns links, never a replacement;
// everything else gets its reason in Deploy Error. That stamp is the door's own dedupe for every
// future run, which is why it is written even when nothing was sent.
// The state arrives as data from the caller and is put on this machine's static data for the rest
// of the finish lane; Build Run Log deletes the slot when it closes the row.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const call = $('Route Mode').first().json;
const D = call.state;
sd[dk] = D;
// isPV is the EMAIL lane: Email Bison confirms membership by read-back into inCamp exactly as PlusVibe does.
const isPV = D.sender === 'PlusVibe' || D.sender === 'Email Bison';
if (D.abort) { D.campsStamped = 0; return [{ json: { _none: true } }]; }
const patches = [];
let deployed = 0, missing = 0, stamped = 0;
const missingIdx = [];
for (const rid of Object.keys(D.rows || {})) {
  const r = D.rows[rid];
  const fields = {};
  let member = false;
  if (isPV) {
    let v = '';
    if (r.skip) v = r.skip;
    else if (D.rbFailed) continue;
    else if (r.email && D.inCamp[r.email]) { v = ''; deployed++; member = true; }
    else { v = 'not in campaign after deploy (dedupe-skipped or PV-dropped)'; missing++; missingIdx.push(patches.length); }
    fields['Deploy Error'] = v;
  } else {
    if (D.hasDeployError) fields['Deploy Error'] = r.skip || '';
    member = !!r.landed;
  }
  if (member && D.stampMirrorRid) {
    const set = {}; for (const c of (r.camps || [])) set[c] = 1; set[D.stampMirrorRid] = 1;
    fields['Campaigns'] = Object.keys(set); stamped++;
  }
  if (Object.keys(fields).length) patches.push({ id: rid, fields });
}
if (isPV) {
  // PlusVibe reports dedupe blocks as counts only, never per email. When every sent-but-absent row
  // is accounted for by those counts, all of them were dedupe and the stamp can say so; any
  // mismatch keeps the honest combined wording, because a chunk failure also lands rows here.
  const dedupeTotal = D.pv ? (Number(D.pv.skipped || 0) + Number(D.pv.already || 0)) : 0;
  if (missing > 0 && missing === dedupeTotal) {
    const lbl = 'blocked by dedupe mode "' + (D.dedupe || 'Strict') + '" (already in the workspace or campaign)';
    for (const i of missingIdx) patches[i].fields['Deploy Error'] = lbl;
  }
  D.deployed = deployed; D.missing = missing;
  // Recomputed at the end, because a row can pick up a skip after the send (rejected by the
  // sequencer's validation, paused by a post-landing gate).
  const skipCounts = {};
  for (const id of Object.keys(D.rows || {})) { const s = D.rows[id].skip; if (s) { const key = s.indexOf('DNC:') === 0 ? 'DNC' : s; skipCounts[key] = (skipCounts[key] || 0) + 1; } }
  D.skipCounts = skipCounts;
  if (deployed && !stamped && !D.rbFailed) D.warnings.push('deployed leads were not stamped with a Campaigns link (no mirror row resolved)');
  D.inCamp = {}; D.emailToRow = {};
} else {
  if (D.landed && !stamped) D.warnings.push('landed prospects were not stamped with a Campaigns link (no mirror row)');
}
D.campsStamped = stamped;
const out = [];
for (let i = 0; i < patches.length; i += 10) out.push({ json: { crBase: D.crBase, tableId: D.tableId, body: { records: patches.slice(i, i + 10), typecast: true } } });
if (!out.length) return [{ json: { _none: true } }];
return out;

// Build Receipt: the Lead Lists row, one per view into one campaign, refreshed by every run of the
// door (a daily feed hits the same row forever, zero new rows). List URL is the client-safe share
// link parsed from the table description; View Link is the internal deep link to the exact
// selector view that deployed, our debugging trail. Deployed is the confirmed member count.
// The stamp writes are collected here too, so a failed PATCH lands in the run's error list.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
try { if ($('Patch Rows').isExecuted) { for (const it of $('Patch Rows').all()) { const j = it.json || {}; if (j.error) D.errors.push('stamp write: ' + JSON.stringify(j.error).slice(0, 200)); } } } catch (e) {}
if (D.abort) { return [{ json: { _none: true, Name: '', Campaign: [], ViewLink: '', InternalLink: '', Deployed: 0 } }]; }
// The receipt is named by the CAMPAIGN on the PlusVibe lane, because that name is what clients
// filter the shared Campaigns view by; the Alta lane names it by the view it drank from. Both
// names are load-bearing for an existing row: the upsert matches on Name plus List URL.
const isEmailLane = (D.sender === 'PlusVibe' || D.sender === 'Email Bison');
D.receiptName = isEmailLane
  ? (D.campName || D.target || ((D.tableName || D.tableId || 'table') + ' - ' + (D.view || 'view')))
  : ((D.tableName || D.tableId || 'table') + ' - ' + (D.view || 'view'));
D.viewLink = D.shareViewLink || '';
if (!D.viewLink) D.warnings.push('share link unresolved; receipt written without a client link');
let internalLink = '';
const stem = D.share || D.shareViewLink || '';
if (stem && D.tableId && D.viewId) internalLink = stem + '/' + D.tableId + '/' + D.viewId;
const deployed = isEmailLane ? Number(D.deployed || 0) : Number(D.landed || 0);
return [{ json: { Name: D.receiptName, Campaign: D.hubCampaignRid ? [D.hubCampaignRid] : [], ViewLink: D.viewLink, InternalLink: internalLink, Deployed: deployed } }];

// Build Run Log: the run's one Hub row, upserted on the CALLER's Execution ID, which is the launch
// row Stamp Running already claimed. One row per run, never two (the Alta lane used to create a
// second row beside the launch row it also updated).
// Status is computed, never a literal, and each lane keeps the verdict it was given: PlusVibe
// reads Succeeded unless something failed; Alta calls a refusal Failed and counts an auto-pause
// as an error. The Description is the narrative a human reads at a glance, and the duplicate
// count in it is a MIRROR, never a gate: the view owns dedupe, and this line is how a view that
// stopped excluding what it already sent shows up on day one instead of quietly spending the
// whole daily allowance re-offering the same people.
// Only the row's real fields are returned: the write maps input straight onto the table.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const D = sd[dk] || { errors: ['deploy state missing'], warnings: [], rows: {}, skipCounts: {}, launchId: '', sender: 'PlusVibe', automation: '', execId: String($execution.id), wfId: '' };
// isPV is the EMAIL lane: Email Bison reports through the same counters (D.pv) the PlusVibe door
// fills, so the narrative below reads the same; the sender's name comes from D.sender.
const isPV = D.sender === 'PlusVibe' || D.sender === 'Email Bison';
const senderName = D.sender || 'PlusVibe';
try { const r = ($('Create Lead List').first() || {}).json || {}; if (!r.id && !D.abort) D.warnings.push('Lead Lists receipt creation failed'); } catch (e) { if (!D.abort) D.warnings.push('Lead Lists receipt not created'); }
const fmt = v => Number(v || 0).toLocaleString('en-US');
const failed = (D.errors || []).slice();
const sc = D.skipCounts || {};
const skipTotal = Object.keys(sc).reduce((s, k) => s + sc[k], 0);
const md = [];
if (isPV) {
  md.push('**Deployed ' + fmt(D.deployed || 0) + ' of ' + fmt(D.rowsTotal || 0) + ' view rows to ' + (D.campName || '?') + '**');
  md.push('');
  md.push('**Campaign:** ' + (D.campName || '?') + ' (' + (D.target || '?') + ')');
  md.push('**Table:** ' + (D.tableName || D.table || '?') + ' (' + (D.tableId || '?') + ')');
  md.push('**View:** ' + (D.view || '?'));
  if (D.viewLink) md.push('**Link:** ' + D.viewLink);
  md.push('**Dedupe mode:** ' + (D.sender === 'Email Bison' ? 'Email Bison (patch existing leads; a lead already In Sequence elsewhere is refused by the sender)' : (D.dedupe || 'Strict')));
  if (D.campsStamped) md.push('**Campaigns links stamped:** ' + fmt(D.campsStamped) + ' (this list = filter Campaigns has the campaign)');
  const P = D.pv;
  if (P) {
    md.push('');
    md.push('**Sent to ' + senderName + '**');
    md.push('- Sent: ' + fmt(P.sent));
    md.push('- Accepted: ' + fmt(P.uploaded));
    md.push('- Not accepted: ' + fmt((P.sent || 0) - (P.uploaded || 0)));
    if (P.skipped) md.push('   - Already in the workspace, blocked by dedupe mode "' + (D.dedupe || 'Strict') + '": ' + fmt(P.skipped));
    if (P.already) md.push('   - Already in this campaign: ' + fmt(P.already));
    if (P.duplicate) md.push('   - Same email twice in the upload: ' + fmt(P.duplicate));
    if (P.invalid) md.push('   - ' + senderName + ' judged the email invalid' + (D.sender === 'Email Bison' ? ' (personal domains are skipped by the instance)' : '') + ': ' + fmt(P.invalid));
    if (P.overflowed) md.push('   - Over your plan limit: ' + fmt(P.overflowed));
    if (P.overwritten) md.push('   - Existing lead refreshed instead of added: ' + fmt(P.overwritten));
    if (P.remaining !== null && P.remaining !== undefined) md.push('- Leads left in plan: ' + fmt(P.remaining));
  }
  const alreadyStamped = sc['already in campaign (Campaigns stamp)'] || 0;
  const pvDupes = (P ? Number(P.skipped || 0) + Number(P.already || 0) : 0);
  md.push('');
  md.push('**Already present: ' + fmt(pvDupes + alreadyStamped) + '** (' + senderName + ': in this campaign ' + fmt(P ? P.already : 0) + ', in the workspace ' + fmt(P ? P.skipped : 0) + ' · Campaigns stamp, caught before sending: ' + fmt(alreadyStamped) + ')');
  if (D.missing) { md.push(''); md.push('- Sent but not found in the campaign afterwards: ' + fmt(D.missing)); }
  const vm = D.varMisses || {};
  const vmKeys = Object.keys(vm).sort((a, b) => vm[b] - vm[a]);
  if (vmKeys.length) {
    md.push('');
    md.push('**Not sent: a required column was empty**');
    md.push('These rows never left Airtable. Fill the column or hide it from the view.');
    for (const k of vmKeys) md.push('- ' + k + ' was empty on ' + fmt(vm[k]) + ' row' + (vm[k] === 1 ? '' : 's'));
  }
  if (skipTotal) {
    md.push('');
    md.push('**Not sent: other reasons (' + fmt(skipTotal) + ')**');
    for (const k of Object.keys(sc)) md.push('- ' + k + ': ' + fmt(sc[k]));
  }
  if (D.receiptName) { md.push(''); md.push('**Lead list receipt:** ' + D.receiptName); }
} else {
  md.push('**Landed ' + fmt(D.landed) + ' of ' + fmt(D.rowsTotal) + ' view rows in ' + (D.campName || D.target || '?') + '**');
  md.push('');
  md.push('**Campaign:** ' + (D.campName || '?') + ' (' + (D.target || '?') + ') · **View:** ' + (D.view || '?') + ' on ' + (D.tableName || D.table || '?') + ' (' + (D.tableId || '?') + ')');
  md.push('');
  md.push('**Funnel**');
  md.push('- **View rows:** ' + fmt(D.rowsTotal));
  if (skipTotal) { md.push('- **Skipped before push (' + fmt(skipTotal) + '):**'); for (const k of Object.keys(sc)) md.push('   - ' + k + ': ' + fmt(sc[k])); }
  md.push('- **Pushed:** ' + fmt(D.pushed));
  md.push('- **Landed (readback):** ' + fmt(D.landed));
  if (D.missing) md.push('- **Pushed but not in the campaign:** ' + fmt(D.missing));
  const pz = (D.pausedTitle || 0) + (D.pausedUrl || 0) + (D.pausedNoData || 0);
  if (pz) { md.push('- **Auto-paused after landing:** ' + fmt(pz) + ' (title rule ' + fmt(D.pausedTitle) + ' · URL mismatch ' + fmt(D.pausedUrl) + ' · no person data ' + fmt(D.pausedNoData) + ')'); for (const n of (D.pausedNames || [])) md.push('   - ' + n); }
  md.push('- **Campaigns links stamped:** ' + fmt(D.campsStamped));
  // Alta's pull-in NEVER reports a duplicate: it answers 200 {"message":"Prospect uploaded
  // successfully"} whether the person is new or already a member. So the count is what we can see
  // by values: rows the Campaigns stamp caught before pushing, plus rows the readback found
  // already in the campaign from before this run started, which is Alta silently absorbing a push.
  const stampDupes = sc['already in campaign (Campaigns stamp)'] || 0;
  let healed = 0; for (const id of Object.keys(D.rows || {})) if (D.rows[id] && D.rows[id].healed) healed++;
  md.push('- **Already present:** ' + fmt(stampDupes + healed) + ' (Campaigns stamp, caught before pushing ' + fmt(stampDupes) + ' · pushed but already a member before this run ' + fmt(healed) + '). Alta never reports a duplicate itself.');
  if (D.receiptName) { md.push(''); md.push('**Lead list receipt:** ' + D.receiptName); }
}
if ((D.warnings || []).length) { md.push(''); md.push('**Warnings (' + D.warnings.length + ')**'); for (const w of D.warnings) md.push('- ' + w); }
if (failed.length) { md.push(''); md.push('**FAILED (' + failed.length + ')**'); for (const e of failed) md.push('- ' + e); }
const pz = (D.pausedTitle || 0) + (D.pausedUrl || 0) + (D.pausedNoData || 0);
const status = isPV
  ? (failed.length ? 'Succeeded with errors' : 'Succeeded')
  : (D.abort ? 'Failed' : ((failed.length || pz || D.missing) ? 'Succeeded with errors' : 'Succeeded'));
const errors = isPV ? failed.length : (failed.length + (pz ? 1 : 0));
const durS = Math.round((Date.now() - (D.startedAt || Date.now())) / 1000);
D.finalStatus = status;
D.finalDescription = md.join('\n');
const row = {
  'Status': status,
  'Trigger': D.trigger || 'form',
  'Run at': D.runAt || new Date().toISOString(),
  'Duration s': durS,
  'Records In': D.rowsTotal || 0,
  'Records Out': (isPV ? (D.deployed || 0) : (D.landed || 0)),
  'Errors': errors,
  'Execution ID': String(D.execId || $execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + (D.wfId || $workflow.id) + '/executions/' + String(D.execId || $execution.id),
  'Description': D.finalDescription.slice(0, 95000)
};
// On a launch row, Automation and Target are LAUNCH PARAMETERS the feed or the Operator wrote, and
// the upsert must not overwrite them: Target holds the campaign id this run was told to deploy
// into, and a run that rewrote it as a description destroyed the record of what it was asked to do
// (caught live, 2026-09-03). Only a run with no launch row of its own fills them in.
if (!D.launchId) {
  row['Automation'] = D.automation || '';
  row['Target'] = (D.tableName || D.table || '') + ' (' + (D.tableId || '') + ') -> ' + (D.campName || D.target || '');
}
return [{ json: row }];

// Finish Out: the receipt back to the door, and the end of this run's slot in static data.
// The door does nothing with it but end; the row is already written, and it is the record.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const D = sd[dk] || {};
delete sd[dk];
let rowId = '';
try { const r = ($input.first() || {}).json || {}; rowId = r.id || ''; } catch (e) {}
return [{ json: {
  ok: true,
  status: D.finalStatus || '',
  rowId: rowId,
  launchId: D.launchId || '',
  campaign: D.campName || D.target || '',
  recordsIn: D.rowsTotal || 0,
  recordsOut: ((D.sender === 'PlusVibe' || D.sender === 'Email Bison') ? (D.deployed || 0) : (D.landed || 0)),
  errors: (D.errors || []).length,
  warnings: (D.warnings || []).length
} }];
